import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  // Create plane geometry with aspect ratio matching atlas region (512:320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Load texture from cache
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create basic material for static composition
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transform from configuration
  const position = config.scenePosition || [0, 0, 0];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  // Setup cleanup
  mesh.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  // Initialize handlers
  mesh.userData.handlers = {};

  return mesh;
}
